# 原地调整资源 (无需重启 Pod)
kubectl patch pod resizable-pod --patch '
{
  "spec": {
    "containers": [{
      "name": "app",
      "resources": {
        "requests": {"cpu": "1000m", "memory": "1Gi"},
        "limits": {"cpu": "2000m", "memory": "2Gi"}
      }
    }]
  }
}'
